// Text I/O with PrintWriter + Scanner (Liang Ch. 14 style)
import java.io.File;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Locale;
import java.util.Scanner;

public class FileIOExample {
    public static void main(String[] args) throws IOException {
        File file = new File("scores.txt");

        // try-with-resources closes (and flushes) the writer even if an exception occurs
        try (PrintWriter output = new PrintWriter(file, "UTF-8")) {
            output.println("Alex 90");
            output.println("Sam 85");
            output.println("Riley 92");
        }
        System.out.println("Wrote " + file.getName() + " (" + file.length() + " bytes)");

        int count = 0;
        int total = 0;
        try (Scanner input = new Scanner(file, "UTF-8")) {
            while (input.hasNext()) {          // false at end of file
                String name = input.next();    // next token, whitespace-separated
                int score = input.nextInt();   // parses the following token as an int
                System.out.println(name + " -> " + score);
                total += score;
                count++;
            }
        }

        double average = count == 0 ? 0.0 : total / (double) count;
        System.out.println("Class average: " + String.format(Locale.ROOT, "%.2f", average));
    }
}

