#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>

int main() {
    const std::string path = "scores.txt";
    {
        // ofstream truncates by default; the destructor closes (and flushes) at the end of this block
        std::ofstream output(path);
        output << "Alex 90\n" << "Sam 85\n" << "Riley 92\n";
    }
    std::cout << "Wrote " << path << " (" << std::filesystem::file_size(path) << " bytes)\n";

    int count = 0;
    int total = 0;
    std::ifstream input(path);
    std::string name;
    int score;
    // >> skips whitespace and reads one token; the loop stops when extraction fails at end of file
    while (input >> name >> score) {
        std::cout << name << " -> " << score << "\n";
        total += score;
        count++;
    }

    double average = count == 0 ? 0.0 : total / static_cast<double>(count);
    std::printf("Class average: %.2f\n", average);
}

