import java.io.FileReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileReaderDemo {
    // Make invisible characters visible in the output
    static String show(int c) {
        return c == '\n' ? "'\\n'" : "'" + (char) c + "'";
    }

    public static void main(String[] args) throws IOException {
        Path path = Path.of("greeting.txt");
        Files.writeString(path, "Hi!\nOK\n", StandardCharsets.UTF_8);

        // read() returns one char as an int (0..65535), or -1 at end of file
        try (FileReader reader = new FileReader(path.toFile(), StandardCharsets.UTF_8)) {
            int c;
            while ((c = reader.read()) != -1) {
                System.out.println("read() -> " + c + " " + show(c));
            }
            System.out.println("read() -> -1 (end of file)");
        }

        // read(char[]) fills a buffer and returns how many chars it stored, or -1 at the end
        try (FileReader reader = new FileReader(path.toFile(), StandardCharsets.UTF_8)) {
            char[] buffer = new char[4];
            int n;
            while ((n = reader.read(buffer)) != -1) {
                String chunk = new String(buffer, 0, n); // only the first n chars are new data
                System.out.println("read(buf) -> " + n + " chars: " + chunk.replace("\n", "\\n"));
            }
        }
    }
}

