#include <fstream>
#include <iostream>
#include <string>

// Make invisible characters visible in the output
std::string show(int c) { return c == '\n' ? "'\\n'" : std::string("'") + static_cast<char>(c) + "'"; }

std::string escape(const std::string& s) {
    std::string out;
    for (char ch : s) out += ch == '\n' ? std::string("\\n") : std::string(1, ch);
    return out;
}

int main() {
    const std::string path = "greeting.txt";
    std::ofstream(path) << "Hi!\nOK\n";  // temporary stream: written and closed in one statement

    // get() returns the next character as an int, or EOF (-1) at end of file
    {
        std::ifstream reader(path);
        int c;
        while ((c = reader.get()) != EOF) {
            std::cout << "read() -> " << c << " " << show(c) << "\n";
        }
        std::cout << "read() -> -1 (end of file)\n";
    }

    // read(buf, n) stores up to n chars; gcount() says how many actually arrived
    {
        std::ifstream reader(path);
        char buffer[4];
        while (reader.read(buffer, sizeof buffer) || reader.gcount() > 0) {
            std::string chunk(buffer, static_cast<size_t>(reader.gcount()));
            std::cout << "read(buf) -> " << reader.gcount() << " chars: " << escape(chunk) << "\n";
        }
    }
}

