import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileWriterModes {
    static final Path PATH = Path.of("journal.txt");

    // Print the file's current contents with newlines made visible, plus its size on disk
    static void report(String label) throws IOException {
        String text = Files.readString(PATH, StandardCharsets.UTF_8);
        System.out.println(label + ": \"" + text.replace("\n", "\\n") + "\" (" + Files.size(PATH) + " bytes)");
    }

    public static void main(String[] args) throws IOException {
        // new FileWriter(file) creates the file, or truncates it to 0 bytes if it exists
        try (FileWriter w = new FileWriter(PATH.toFile(), StandardCharsets.UTF_8)) {
            w.write("line 1\n");
            w.write("line 2\n");
        }
        report("first write");

        try (FileWriter w = new FileWriter(PATH.toFile(), StandardCharsets.UTF_8)) {
            w.write("fresh start\n"); // the old two lines are gone
        }
        report("overwrite");

        // The boolean 'append' flag keeps the old content and writes at the end
        try (FileWriter w = new FileWriter(PATH.toFile(), StandardCharsets.UTF_8, true)) {
            w.write("appended\n");
        }
        report("append");

        // Buffered data stays in memory until flush() or close()
        BufferedWriter buffered = new BufferedWriter(new FileWriter(PATH.toFile(), StandardCharsets.UTF_8));
        buffered.write("draft\n");
        System.out.println("buffered, before close: " + Files.size(PATH) + " bytes on disk");
        buffered.close(); // close() flushes first; forgetting it would lose "draft"
        System.out.println("buffered, after close:  " + Files.size(PATH) + " bytes on disk");
    }
}

