    }  // destructor closes the file here
    report("first write");

    {
        std::ofstream w(PATH);
        w << "fresh start\n";
    }
    report("overwrite");

    {
        std::ofstream w(PATH, std::ios::app);  // append mode: every write goes to the end
        w << "appended\n";
    }
    report("append");

    // ofstream is buffered: small writes stay in memory until flush/close
    std::ofstream buffered(PATH);
    buffered << "draft\n";
    std::cout << "buffered, before close: " << std::filesystem::file_size(PATH) << " bytes on disk\n";
    buffered.close();
