// fs.writeSync is unbuffered, so this tiny class buffers in memory like BufferedWriter:
// nothing reaches the disk until close() flushes the pending text.
class BufferedWriter {
  constructor(path) {
    this.fd = fs.openSync(path, 'w');
    this.pending = '';
  }

  write(text) { this.pending += text; }

  close() {
    fs.writeSync(this.fd, this.pending);
    fs.closeSync(this.fd);
  }
}

