import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.TreeMap;

public class BufferedReaderLog {
    public static void main(String[] args) throws IOException {
        Path log = Path.of("server.log");
        Files.writeString(log, """
                INFO  server started
                WARN  disk 85% full

                ERROR request 17 failed
                INFO  request 18 ok
                ERROR request 19 failed
                """, StandardCharsets.UTF_8);

        Map<String, Integer> perLevel = new TreeMap<>();
        int lineNumber = 0;
        // BufferedReader reads big chunks (8192 chars) from the file and hands out one line at a time
        try (BufferedReader reader = Files.newBufferedReader(log, StandardCharsets.UTF_8)) {
            String line;
            while ((line = reader.readLine()) != null) { // null, not "", signals end of file
                lineNumber++;
                if (line.isBlank()) {
                    System.out.println(lineNumber + ": (blank, skipped)");
                    continue;
                }
                // readLine strips the line terminator, so line has no trailing '\n'
                String level = line.substring(0, line.indexOf(' '));
                String message = line.substring(level.length()).trim();
                perLevel.merge(level, 1, Integer::sum);
                System.out.println(lineNumber + ": [" + level + "] " + message);
            }
        }
        System.out.println("lines read: " + lineNumber);
        System.out.println("count per level: " + perLevel);
    }
}

