int main() {
    const std::string path = "server.log";
    std::ofstream(path) << "INFO  server started\n"
                        << "WARN  disk 85% full\n"
                        << "\n"
                        << "ERROR request 17 failed\n"
                        << "INFO  request 18 ok\n"
                        << "ERROR request 19 failed\n";

    std::map<std::string, int> perLevel;
    int lineNumber = 0;
    // ifstream is buffered; std::getline returns one line without its '\n'
    std::ifstream reader(path);
    std::string line;
    while (std::getline(reader, line)) {  // the stream turns false at end of file
        lineNumber++;
        if (line.find_first_not_of(" \t") == std::string::npos) {
            std::cout << lineNumber << ": (blank, skipped)\n";
            continue;
        }
        std::string level = line.substr(0, line.find(' '));
        std::string message = line.substr(line.find_first_not_of(' ', level.size()));
        perLevel[level] += 1;
        std::cout << lineNumber << ": [" << level << "] " << message << "\n";
    }
    std::cout << "lines read: " << lineNumber << "\n";
    std::cout << "count per level: {";
    bool first = true;
    for (const auto& [level, count] : perLevel) {
        std::cout << (first ? "" : ", ") << level << "=" << count;
        first = false;
    }
    std::cout << "}\n";
}

