import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import java.util.Scanner;

public class ScannerTokens {
    public static void main(String[] args) throws IOException {
        Path path = Path.of("readings.txt");
        // Tokens are separated by any whitespace: spaces, tabs and newlines all count
        Files.writeString(path, "5 oops\n7   3.5\n12\n-4 end\n", StandardCharsets.UTF_8);

        int sum = 0;
        int ints = 0;
        try (Scanner in = new Scanner(path, StandardCharsets.UTF_8)) {
            in.useLocale(Locale.ROOT); // number parsing is locale-sensitive (e.g. "3.5" vs "3,5")
            while (in.hasNext()) {
                // Peek before consuming: nextInt() on "oops" would throw InputMismatchException
                if (in.hasNextInt()) {
                    int value = in.nextInt();
                    sum += value;
                    ints++;
                    System.out.println("int " + value + " (running sum " + sum + ")");
                } else {
                    System.out.println("skip \"" + in.next() + "\""); // next() consumes the bad token
                }
            }
        }
        System.out.println("ints read: " + ints + ", sum: " + sum);

        // A Scanner can also read from a String with a custom delimiter
        try (Scanner csv = new Scanner("ada,36,london").useDelimiter(",")) {
            String name = csv.next();
            int age = csv.nextInt();
            String city = csv.next();
            System.out.println("csv -> name=" + name + ", age=" + age + ", city=" + city);
        }
    }
}

