#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

// Strict integer check: std::stoi("3.5") would quietly return 3, so verify that
// the whole token was consumed.
bool parseInt(const std::string& token, int& out) {
    try {
        size_t used = 0;
        out = std::stoi(token, &used);
        return used == token.size();
    } catch (const std::exception&) {
        return false;
    }
}

int main() {
    const std::string path = "readings.txt";
    std::ofstream(path) << "5 oops\n7   3.5\n12\n-4 end\n";

    int sum = 0;
    int ints = 0;
    std::ifstream in(path);
    std::string token;
    while (in >> token) {  // >> into a string reads one whitespace-separated token
        int value;
        if (parseInt(token, value)) {
            sum += value;
            ints++;
            std::cout << "int " << value << " (running sum " << sum << ")\n";
        } else {
            std::cout << "skip \"" << token << "\"\n";
        }
    }
    std::cout << "ints read: " << ints << ", sum: " << sum << "\n";

    // getline with a delimiter character splits a string on commas
    std::istringstream csv("ada,36,london");
    std::string name, ageText, city;
    std::getline(csv, name, ',');
    std::getline(csv, ageText, ',');
    std::getline(csv, city, ',');
    std::cout << "csv -> name=" << name << ", age=" << std::stoi(ageText) << ", city=" << city << "\n";
}

