import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

public class PathApiTour {
    public static void main(String[] args) throws IOException {
        Path root = Path.of("atlas-demo");
        // Start clean so the program can be re-run: delete deepest paths first
        if (Files.exists(root)) {
            try (Stream<Path> old = Files.walk(root)) {
                for (Path p : old.sorted(Comparator.reverseOrder()).toList()) {
                    Files.delete(p);
                }
            }
        }

        // A Path is just a name; nothing touches the disk until a Files method runs
        Path notes = root.resolve("notes");
        Path week1 = notes.resolve("week1.txt");
        System.out.println("path:       " + week1);
        System.out.println("file name:  " + week1.getFileName());
        System.out.println("parent:     " + week1.getParent());
        System.out.println("normalize:  " + Path.of("atlas-demo/notes/../notes/./week1.txt").normalize());

        Files.createDirectories(notes); // creates every missing parent, no error if it exists
        Files.writeString(week1, "arrays\nlists\n", StandardCharsets.UTF_8);
        Files.write(notes.resolve("week2.txt"), List.of("maps", "sets", "lambdas"), StandardCharsets.UTF_8);

        // Whole-file read: fine for small files, O(file size) memory
        List<String> lines = Files.readAllLines(week1, StandardCharsets.UTF_8);
        System.out.println("readAllLines(week1): " + lines);

        // Streaming read: Files.lines is lazy and must be closed, hence try-with-resources
        try (Stream<String> stream = Files.lines(notes.resolve("week2.txt"), StandardCharsets.UTF_8)) {
            long count = stream.filter(l -> l.startsWith("l")).count();
            System.out.println("lines starting with 'l' in week2: " + count);
        }

        System.out.println("size of week1: " + Files.size(week1) + " bytes");
        System.out.println("exists(week3)? " + Files.exists(notes.resolve("week3.txt")));

        // walk visits the whole tree; sort because directory order is not guaranteed
        System.out.println("walk:");
        try (Stream<Path> tree = Files.walk(root)) {
            tree.map(Path::toString).sorted().forEach(p -> System.out.println("  " + p));
        }
    }
}

