namespace fs = std::filesystem;

int main() {
    fs::path root = "atlas-demo";
    fs::remove_all(root);  // start clean so the program can be re-run

    // operator/ joins path components, like Path.resolve
    fs::path notes = root / "notes";
    fs::path week1 = notes / "week1.txt";
    std::cout << "path:       " << week1.string() << "\n";
    std::cout << "file name:  " << week1.filename().string() << "\n";
    std::cout << "parent:     " << week1.parent_path().string() << "\n";
    std::cout << "normalize:  " << fs::path("atlas-demo/notes/../notes/./week1.txt").lexically_normal().string() << "\n";

    fs::create_directories(notes);
    std::ofstream(week1) << "arrays\nlists\n";
    std::ofstream(notes / "week2.txt") << "maps\nsets\nlambdas\n";

    std::vector<std::string> lines;
    {
        std::ifstream in(week1);
        for (std::string line; std::getline(in, line);) lines.push_back(line);
    }
    std::cout << "readAllLines(week1): [";
    for (size_t i = 0; i < lines.size(); ++i) std::cout << (i ? ", " : "") << lines[i];
    std::cout << "]\n";

    // Streaming read: one line in memory at a time
    int count = 0;
    std::ifstream in2(notes / "week2.txt");
    for (std::string line; std::getline(in2, line);) {
        if (!line.empty() && line[0] == 'l') count++;
    }
    std::cout << "lines starting with 'l' in week2: " << count << "\n";

    std::cout << "size of week1: " << fs::file_size(week1) << " bytes\n";
    std::cout << std::boolalpha << "exists(week3)? " << fs::exists(notes / "week3.txt") << "\n";

    // recursive_directory_iterator skips the root itself, so add it by hand
    std::vector<std::string> tree = {root.string()};
    for (const auto& entry : fs::recursive_directory_iterator(root)) tree.push_back(entry.path().string());
    std::sort(tree.begin(), tree.end());
    std::cout << "walk:\n";
    for (const auto& p : tree) std::cout << "  " << p << "\n";
}

